import os, sys, traceback
import click
from click.testing import CliRunner

runner = CliRunner()
print("click version:", click.__version__, "file:", click.__file__)

def run(name, cmd, args=None, env=None, prefix=None):
    args = args or []
    env = env or {}
    kw = {}
    if prefix is not None:
        kw["auto_envvar_prefix"] = prefix
    try:
        r = runner.invoke(cmd, args, env=env, standalone_mode=False, **kw)
    except Exception as e:
        print(f"{name}: EXC {type(e).__name__}: {e}")
        return
    if r.exception is not None:
        print(f"{name}: EXCEPTION {type(r.exception).__name__}: {r.exception}")
        return
    print(f"{name}: return_value={r.return_value!r}")

# 1. boolean flag with envvar
for v in ['1','0','true','false','','yes','on','no',' True ']:
    @click.command()
    @click.option('--flag', is_flag=True, envvar='FLAG')
    def c1(flag):
        return flag
    run(f"boolflag env={v!r}", c1, [], {'FLAG': v})

